//! Slint desktop UI for CloudStream.
//!
//! Slint's generated bindings use a small amount of `unsafe`; this crate keeps that confined to
//! the include_modules expansion (same pattern as `player_mpv` for FFI).
#![deny(unsafe_code)]
#![allow(missing_docs)]

mod background_work;
mod bridge;
mod focus_grid;
mod playback_watch;
mod posters;
mod request_tickets;
mod startup_progress;
mod ui_events;

pub use app_services::UiServices;
pub use bridge::{run_desktop_app, run_desktop_app_with, AppExtras, WipeRequest};

/// Code generated by `slint-build` from `ui/*.slint`. It is not ours to change, so the workspace's
/// strict lints (no unwrap, no indexing, line limits) do not apply to it.
#[allow(
    unsafe_code,
    clippy::all,
    clippy::pedantic,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::todo,
    clippy::unreachable,
    clippy::indexing_slicing,
    clippy::cognitive_complexity
)]
mod generated {
    slint::include_modules!();
}

pub use generated::*;
